package p_cdbf3019a3a300007f3d219dbc66ccf3
import("testing"; r_ "gopurs/output/gopurs_runtime")
var arrayOpsSink int64
func prototypeRangeSum(start,end int64) int64 {
 result:=int64(0); step:=int64(1); if start>end {step=-1}
 for x:=start;;x+=step {if r_.IntMod(x,2)==0 {result=r_.IntAdd(result,x)}; if x==end {break}}
 return result
}
func TestArrayOpsPrototype(t *testing.T) {
 for _,n:=range []int64{-100,-2,-1,0,1,2,3,5,10,899,900,901,2000} {
  got:=Call_Test_ArrayOps_sumEvens(n); want:=prototypeRangeSum(1,n)
  if got!=want {t.Fatalf("n=%d got=%d want=%d",n,got,want)}
 }
}
func BenchmarkArrayOpsBefore(b *testing.B){b.ReportAllocs(); for i:=0;i<b.N;i++ {arrayOpsSink=Call_Test_ArrayOps_sumEvens(900)}}
func BenchmarkArrayOpsPrototype(b *testing.B){b.ReportAllocs(); for i:=0;i<b.N;i++ {arrayOpsSink=prototypeRangeSum(1,900)}}

func TestArrayOpsIndependentOracle(t *testing.T) {
 cases:=[]int64{-100000,-65537,-65536,65535,65536,65537,100000}
 for n:=int64(-1000); n<=2000; n++ {cases=append(cases,n)}
 for _,n:=range cases {
  k:=n/2; want:=int64(0)
  if n>=1 {want=int64(int32(k*(k+1)))} else {want=int64(int32(-k*(k-1)))}
  got:=Call_Test_ArrayOps_sumEvens(n)
  if got!=want {t.Fatalf("n=%d got=%d want=%d",n,got,want)}
 }
}
